    @EventHandler( payloadType=CreateGiftCardEvent.class )
    public void handle( CreateGiftCardEvent event) {
	    LOGGER.info("handling CreateGiftCardEvent - " + event );
	    GiftCard entity = new GiftCard();
            entity.setGiftCardId( event.getGiftCardId() );
            entity.setCode( event.getCode() );
            entity.setBalance( event.getBalance() );
            entity.setExpirationDate( event.getExpirationDate() );
            entity.setStatus( event.getStatus() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllGiftCard( entity );
    }

