    /**
     * Method to retrieve the GiftCard via an GiftCardPrimaryKey.
     * @param 	id Long
     * @return 	GiftCard
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public GiftCard handle( FindGiftCardQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getGiftCardId() );
    }
    
    /**
     * Method to retrieve a collection of all GiftCards
     *
     * @param	query	FindAllGiftCardQuery 
     * @return 	List<GiftCard> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<GiftCard> handle( FindAllGiftCardQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindGiftCard,
 * but only if the id matches
 *
 * @param		entity	GiftCard
 */
	protected void emitFindGiftCard( GiftCard entity ) {
		LOGGER.info("handling emitFindGiftCard" );
		
	    queryUpdateEmitter.emit(FindGiftCardQuery.class,
	                            query -> query.getFilter().getGiftCardId().equals(entity.getGiftCardId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllGiftCard
	 * 
	 * @param		entity	GiftCard
	 */
	protected void emitFindAllGiftCard( GiftCard entity ) {
		LOGGER.info("handling emitFindAllGiftCard" );
		
	    queryUpdateEmitter.emit(FindAllGiftCardQuery.class,
	                            query -> true,
	                            entity);
	}

